<section class="container section"><div class="section-heading"><div><p class="eyebrow"><?php esc_html_e( 'Popular right now', 'souqify' ); ?></p><h2><?php esc_html_e( 'Trending products.', 'souqify' ); ?></h2></div><a class="text-link" href="#"><?php esc_html_e( 'Shop all', 'souqify' ); ?> →</a></div><?php if ( class_exists( 'WooCommerce' ) ) : ?><div class="products-grid"><?php $query = new WP_Query( array( 'post_type' => 'product', 'posts_per_page' => 8, 'post_status' => 'publish', 'meta_key' => 'total_sales', 'orderby' => 'meta_value_num', 'order' => 'DESC' ) ); if ( $query->have_posts() ) { while ( $query->have_posts() ) { $query->the_post(); get_template_part( 'template-parts/product/product-card' ); } wp_reset_postdata(); } else { echo '<p class="no-products">' . esc_html__( 'Your most popular products will appear here.', 'souqify' ) . '</p>'; } ?></div><?php endif; ?></section>
